vec3 makecol(int index) {
    vec3 outcol;
    outcol = vec3(sin(float(index) * 0.05) + 0.2 * sin(float(index) * 1.52));
    return outcol;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {

    vec3 outcol = vec3(0.0, 0.0, 0.0);

    /* Settings */

    float coord_real = -1.2425949321642230015045;
    float coord_imag = 0.38239211419691225407579;
    float coord_size = 0.002 * exp(8.0 * cos(0.25 * iTime));
    float escape_radius = 2.0;
    int max_iter = 300;

    /* End of settings */

    float escape_radius_sqr = escape_radius * escape_radius;
    float width = iResolution.x * 0.5;
    float height = iResolution.y;

    if (fragCoord.x < width) {

        /* Left screen */

        /* Setup cartesian plane */

        float cx = (fragCoord.x - 0.5 * width) / width;
        float cy = (fragCoord.y - 0.5 * height) / width;

        /* parameter transformation */

        cx = coord_size * cx + coord_real;
        cy = coord_size * cy + coord_imag;

        /* fractal */

        float zx = 0.0;
        float zy = 0.0;
        int iter = 0;
        while (iter < max_iter) {

            float tmp = zx * zx - zy * zy + cx;
            zy = 2.0 * zx * zy + cy;
            zx = tmp;
            if (zx * zx + zy * zy > escape_radius_sqr) break;
            iter++;

        }

        if (iter < max_iter) {
            outcol = makecol(iter);
        }
    } else {

        /* Right screen */

        /* Setup exp-plane */

        float cx = (fragCoord.x / width) * 6.283185307179586;
        float cy = (fragCoord.y / width) * 6.283185307179586;
        float tmp = cos(cx) * exp(cy) / width;
        cy = sin(cx) * exp(cy) / width;
        cx = tmp;

        /* parameter transformation */

        cx = coord_size * cx + coord_real;
        cy = coord_size * cy + coord_imag;

        /* fractal */

        float zx = 0.0;
        float zy = 0.0;
        int iter = 0;
        while (iter < max_iter) {

            float tmp = zx * zx - zy * zy + cx;
            zy = 2.0 * zx * zy + cy;
            zx = tmp;
            if (zx * zx + zy * zy > escape_radius_sqr) break;
            iter++;

        }

        if (iter < max_iter) {
            outcol = makecol(iter);
        }
    }

    fragColor = vec4(outcol, 1.0);
}
